1	/**
2	 * Shared-hosting primitives (Phase 1 foundation).
3	 *
4	 * Pure, framework-free helpers the account lifecycle is built on — unit-tested so
5	 * the parts that end up in a shell command on a MULTI-TENANT box (a username, a
6	 * quota, a domain in an nginx `server_name`) are provably well-formed before they
7	 * ever get there. On a shared box a single bad interpolation is not one
8	 * customer's bug, it is everyone's; these validators are the first line of that.
9	 */
10	
11	/** A syntactically valid domain for a name-based vhost (no scheme, no path). */
12	const DOMAIN_RE = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
13	
14	/** True for a hostname safe to place in an nginx `server_name` / a cert request. */
15	export function isValidHostingDomain(domain: string): boolean {
16	  const d = String(domain ?? "").trim().toLowerCase().replace(/\.$/, "");
17	  return DOMAIN_RE.test(d);
18	}
19	
20	export function normalizeHostingDomain(domain: string): string {
21	  return String(domain ?? "").trim().toLowerCase().replace(/^www\./, "").replace(/\.$/, "");
22	}
23	
24	/**
25	 * Canonical form of a hostname for the HostingHostnameClaim registry: trimmed,
26	 * lowercased, trailing dot stripped. Applied on BOTH the claim insert and every
27	 * lookup/free, so a case/format variant can never dodge the UNIQUE(hostname).
28	 * Deliberately does NOT strip a leading `www.` (unlike normalizeHostingDomain) —
29	 * a claim reserves the exact nginx `server_name` that will be served.
30	 */
31	export function normalizeClaimHostname(name: string): string {
32	  return String(name ?? "").trim().toLowerCase().replace(/\.$/, "");
33	}
34	
35	/**
36	 * A safe jailed Linux username for an account, derived deterministically and kept
37	 * short (Linux caps usernames at 32 chars; some tooling chokes past 16). Starts
38	 * with a letter, lowercase alnum only — nothing a shell could ever interpret.
39	 *
40	 * `seed` (email localpart or account id) proposes a readable base; `disambiguator`
41	 * (a slice of the account id) guarantees per-node uniqueness without a DB probe.
42	 * The result still has to pass `isValidUnixUsername` before use, and the caller
43	 * resolves any residual collision against the DB (`@@unique([hostingNodeId, username])`).
44	 */
45	export function deriveUsername(seed: string, disambiguator: string): string {
46	  const base = String(seed ?? "")
47	    .toLowerCase()
48	    .replace(/[^a-z0-9]/g, "")
49	    .replace(/^[0-9]+/, "") // must not start with a digit
50	    .slice(0, 8);
51	  const suffix = String(disambiguator ?? "")
52	    .toLowerCase()
53	    .replace(/[^a-z0-9]/g, "")
54	    .slice(0, 6);
55	  // Guarantee a non-empty body so the result always clears the min-length rule
56	  // even when both inputs sanitise away to nothing.
57	  const body = `${base}${suffix}` || "acct";
58	  return `nx${body}`.slice(0, 16);
59	}
60	
61	const UNIX_USER_RE = /^[a-z][a-z0-9]{2,31}$/;
62	
63	/** True only for a shell-inert, policy-valid Linux username. */
64	export function isValidUnixUsername(name: string): boolean {
65	  return UNIX_USER_RE.test(String(name ?? ""));
66	}
67	
68	/**
69	 * Base zone for the FREE temporary hosting subdomain a customer can start on
70	 * before they connect a real domain (`<username>.nxeon.cloud`). Env-overridable so
71	 * a different install can point it at its own wildcard zone. The customer's account
72	 * `username` is already a shell-inert, per-node-unique slug (deriveUsername), so
73	 * `<username>.<base>` is a valid, collision-safe hostname claimed with kind PRIMARY
74	 * exactly like a real domain — the hostname-uniqueness guard is identical.
75	 */
76	export const HOSTING_SUBDOMAIN_BASE = process.env.HOSTING_SUBDOMAIN_BASE || "sites.nxeon.cloud";
77	
78	/** The free temporary subdomain for an account username, e.g. `nxjane.sites.nxeon.cloud`. */
79	export function tempSubdomainFor(username: string): string {
80	  return `${username}.${HOSTING_SUBDOMAIN_BASE}`;
81	}
82	
83	/**
84	 * The free subdomain for a customer-chosen label, e.g. `mysite.sites.nxeon.cloud`.
85	 * The label is validated (isValidSubdomainLabel) and de-duplicated by the same
86	 * atomic UNIQUE(hostname) claim a real domain gets — see orderHostingAccount.
87	 */
88	export function freeSubdomainFor(label: string): string {
89	  return `${String(label ?? "").trim().toLowerCase()}.${HOSTING_SUBDOMAIN_BASE}`;
90	}
91	
92	/**
93	 * True when a hostname is one of OUR free wildcard subdomains (the account's
94	 * website lives at `<label>.<HOSTING_SUBDOMAIN_BASE>`). These resolve automatically
95	 * via the `*.<base>` wildcard A record, so the customer never has to point DNS or
96	 * add an A record — the portal shows "live" instead of the point-your-domain flow.
97	 */
98	export function isFreeSubdomain(host: string): boolean {
99	  const h = String(host ?? "").trim().toLowerCase().replace(/\.$/, "");
100	  return h === HOSTING_SUBDOMAIN_BASE || h.endsWith(`.${HOSTING_SUBDOMAIN_BASE}`);
101	}
102	
103	export type HostingPlanLimits = {
104	  diskGB: number;
105	  maxSites: number;
106	  maxDatabases: number;
107	  bandwidthTB: number;
108	  phpVersions: string[];
109	};
110	
111	/** The effective, sanitised limits for an account, snapshotted from its plan. */
112	export function planLimits(plan: {
113	  diskGB: number;
114	  maxSites: number;
115	  maxDatabases: number;
116	  bandwidthTB: number;
117	  phpVersions: string;
118	}): HostingPlanLimits {
119	  const php = String(plan.phpVersions ?? "")
120	    .split(",")
121	    .map((v) => v.trim())
122	    .filter((v) => /^\d\.\d$/.test(v));
123	  return {
124	    diskGB: Math.max(1, Math.floor(plan.diskGB || 1)),
125	    maxSites: Math.max(1, Math.floor(plan.maxSites || 1)),
126	    maxDatabases: Math.max(0, Math.floor(plan.maxDatabases || 0)),
127	    bandwidthTB: Math.max(0, plan.bandwidthTB || 0),
128	    phpVersions: php.length ? php : ["8.3"],
129	  };
130	}
131	
132	/** Disk quota in KB blocks for `setquota` (1 GB = 1,048,576 one-KB blocks). */
133	export function diskQuotaBlocks(diskGB: number): number {
134	  return Math.max(1, Math.floor(diskGB)) * 1024 * 1024;
135	}
136	
137	/**
138	 * Inode (file-count) quota for `setquota`, the containment for a DoS the block
139	 * quota alone doesn't stop: a tenant creating MILLIONS of tiny files exhausts the
140	 * shared filesystem's inode table — filling no disk blocks but breaking every
141	 * neighbour's ability to create a file. `setquota … <isoft> <ihard>` of `0 0`
142	 * means UNLIMITED inodes, so a real cap is required here. Scales gently off the
143	 * plan's disk size but is floored (a 1 GB plan still gets working room) and
144	 * ceilinged (a huge plan can't effectively uncap); hard carries 25% headroom
145	 * over soft so a tenant hits the soft warning before the hard wall.
146	 */
147	export function diskQuotaInodes(diskGB: number): { soft: number; hard: number } {
148	  const gb = Math.max(1, Math.floor(diskGB || 1));
149	  const soft = Math.min(2_000_000, Math.max(200_000, gb * 50_000));
150	  const hard = Math.floor(soft * 1.25);
151	  return { soft, hard };
152	}
153	
154	/**
155	 * What the customer sets in DNS to point a domain at their account: an A record
156	 * to the node's shared public IP. (A CNAME to the node FQDN is offered too when
157	 * the node has one, for sub-domains / apex-ALIAS providers.)
158	 */
159	export function pointToRecords(node: { publicIp: string; hostnameFqdn?: string | null }): {
160	  aRecord: string;
161	  cnameTarget: string | null;
162	} {
163	  return { aRecord: node.publicIp, cnameTarget: node.hostnameFqdn?.trim() || null };
164	}
165	
166	/** The absolute home + web root for an account's jailed user. */
167	export function accountPaths(username: string): { home: string; webroot: string; fpmPool: string } {
168	  return {
169	    home: `/home/${username}`,
170	    webroot: `/home/${username}/public_html`,
171	    fpmPool: `/etc/php/fpm-pools/${username}.conf`,
172	  };
173	}
174	
175	/**
176	 * Per-account directory holding the self-signed FALLBACK cert generated at
177	 * provision time (fullchain.pem + privkey.pem). Its whole purpose: nginx can
178	 * `listen 443 ssl` from the moment the account exists, so HTTPS shows a cert
179	 * WARNING, never ERR_CONNECTION_REFUSED — the real Let's Encrypt cert replaces it
180	 * once the SSL sweep issues one. Username is already validated before this reaches
181	 * a shell (isValidUnixUsername), same as accountPaths. */
182	export function selfSignedCertDir(username: string): string {
183	  return `/etc/ssl/hosting/${username}`;
184	}
185	
186	/**
187	 * A single DNS label for a subdomain (the part left of the primary domain, e.g.
188	 * "shop" in shop.example.com). No dots — a subdomain is exactly one label deep;
189	 * lowercase alnum + internal hyphens only, so it is shell-inert AND a valid
190	 * hostname label + directory name.
191	 */
192	const SUB_LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])?$/;
193	export function isValidSubdomainLabel(label: string): boolean {
194	  return SUB_LABEL_RE.test(String(label ?? "").trim().toLowerCase());
195	}
196	
197	/**
198	 * A hard-to-guess token for the Adminer DB-manager directory dropped inside an
199	 * account's webroot (`/nxtools-<token>/adminer.php`). Lowercase alnum only, so it
200	 * is shell-inert AND a valid nginx-served directory name; length-bounded to keep
201	 * it unguessable without being unwieldy. The real access control is the tenant's
202	 * scoped DB login, not the token — this just keeps the path off casual discovery.
203	 */
204	const DBTOOL_TOKEN_RE = /^[a-z0-9]{16,40}$/;
205	export function isValidDbToolToken(token: string): boolean {
206	  return DBTOOL_TOKEN_RE.test(String(token ?? ""));
207	}
208	
209	/** Docroot + parent dir for a subdomain, jailed under the account home. */
210	export function subdomainPaths(username: string, label: string): { dir: string; docroot: string } {
211	  const dir = `/home/${username}/subdomains/${label}`;
212	  return { dir, docroot: `${dir}/public_html` };
213	}
214	
215	/** Docroot + parent dir for an addon domain, jailed under the account home. */
216	export function addonDomainPaths(username: string, domain: string): { dir: string; docroot: string } {
217	  const dir = `/home/${username}/domains/${domain}`;
218	  return { dir, docroot: `${dir}/public_html` };
219	}
220	
221	/**
222	 * The branded "your site is ready" page written into an EMPTY docroot at provision
223	 * time, so a freshly provisioned site (or new subdomain/addon) shows a polished Nxeon
224	 * placeholder instead of a bare nginx 403. It is only ever written when no
225	 * index.html / index.php already exists, and any real content the customer uploads
226	 * (or a WordPress/app install's index.php) supersedes it — nginx's `index index.php
227	 * index.html` order means an installed app wins automatically.
228	 *
229	 * Self-contained: inline CSS, system-font stack, no external assets (the box has no
230	 * asset-fetch guarantee and external fonts may be blocked). `domain` is only ever a
231	 * validated hostname ([a-z0-9.-]) so it is safe to interpolate into the markup, and
232	 * the string is written via a QUOTED heredoc so the shell never interprets it.
233	 */
234	export function hostingParkingPage(domain: string): string {
235	  const host = String(domain ?? "").trim() || "your site";
236	  return `<!doctype html>
237	<html lang="en">
238	<head>
239	<meta charset="utf-8">
240	<meta name="viewport" content="width=device-width, initial-scale=1">
241	<meta name="robots" content="noindex">
242	<title>${host} — coming soon</title>
243	<style>
244	  :root { color-scheme: dark; }
245	  * { box-sizing: border-box; margin: 0; padding: 0; }
246	  body {
247	    min-height: 100vh; display: grid; place-items: center; padding: 24px;
248	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
249	    color: #e8ecf5; background: #070b18;
250	    background-image:
251	      radial-gradient(60rem 60rem at 15% -10%, rgba(124,92,255,0.18), transparent 60%),
252	      radial-gradient(50rem 50rem at 110% 10%, rgba(34,211,238,0.14), transparent 55%);
253	  }
254	  .card {
255	    width: 100%; max-width: 560px; text-align: center;
256	    padding: 48px 40px; border-radius: 20px;
257	    background: rgba(17,24,42,0.72);
258	    border: 1px solid rgba(255,255,255,0.08);
259	    box-shadow: 0 30px 80px -30px rgba(0,0,0,0.8);
260	    backdrop-filter: blur(8px);
261	  }
262	  .badge {
263	    display: inline-flex; align-items: center; gap: 8px;
264	    font-size: 12px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase;
265	    color: #a9b6d6; padding: 6px 12px; border-radius: 999px;
266	    border: 1px solid rgba(255,255,255,0.1); background: rgba(255,255,255,0.03);
267	  }
268	  .dot { width: 8px; height: 8px; border-radius: 50%; background: #34d399; box-shadow: 0 0 12px #34d399; }
269	  h1 { font-size: 30px; line-height: 1.15; margin: 22px 0 10px; font-weight: 700; letter-spacing: -0.02em; }
270	  .domain {
271	    background: linear-gradient(90deg, #a78bfa, #22d3ee);
272	    -webkit-background-clip: text; background-clip: text; color: transparent;
273	    word-break: break-all;
274	  }
275	  p { color: #aab3c9; font-size: 15px; line-height: 1.6; margin: 0 auto; max-width: 42ch; }
276	  .steps { list-style: none; margin: 26px 0 0; display: grid; gap: 10px; text-align: left; }
277	  .steps li {
278	    display: flex; gap: 12px; align-items: flex-start;
279	    font-size: 14px; color: #c6cee0; padding: 12px 14px;
280	    border: 1px solid rgba(255,255,255,0.07); border-radius: 12px; background: rgba(255,255,255,0.02);
281	  }
282	  .steps b { color: #fff; font-weight: 600; }
283	  .n { flex: none; width: 22px; height: 22px; border-radius: 7px; display: grid; place-items: center;
284	       font-size: 12px; font-weight: 700; color: #070b18; background: linear-gradient(135deg, #a78bfa, #22d3ee); }
285	  footer { margin-top: 28px; font-size: 12px; color: #6b7590; }
286	  footer a { color: #9fb0d6; text-decoration: none; }
287	</style>
288	</head>
289	<body>
290	  <main class="card">
291	    <span class="badge"><span class="dot"></span>Site is live</span>
292	    <h1>Your website is ready<br><span class="domain">${host}</span></h1>
293	    <p>This is a temporary placeholder. Your hosting is active — add your site and this page disappears automatically.</p>
294	    <ol class="steps">
295	      <li><span class="n">1</span><span><b>Install an app</b> — one-click WordPress and more from your Nxeon dashboard.</span></li>
296	      <li><span class="n">2</span><span><b>Or upload your files</b> — connect over SFTP or the file manager and drop them in <b>public_html</b>.</span></li>
297	      <li><span class="n">3</span><span><b>Point your domain</b> — add a real domain and free SSL from the dashboard.</span></li>
298	    </ol>
299	    <footer>Powered by <a href="https://nxeon.cloud">Nxeon</a></footer>
300	  </main>
301	</body>
302	</html>
303	`;
304	}
305	
306	/**
307	 * True for a well-formed 5-field cron schedule ("m h dom mon dow"). Each field is
308	 * restricted to the digits/ranges/steps/lists/`*` cron uses — nothing that could
309	 * be a shell metacharacter — so the schedule is safe to write into a crontab.
310	 * (Named shortcuts like @daily are intentionally NOT accepted here.)
311	 */
312	const CRON_FIELD_RE = /^[0-9*/,\-]+$/;
313	export function isValidCronSchedule(schedule: string): boolean {
314	  const parts = String(schedule ?? "").trim().split(/\s+/);
315	  if (parts.length !== 5) return false;
316	  return parts.every((p) => p.length > 0 && p.length <= 40 && CRON_FIELD_RE.test(p));
317	}
318	
319	/**
320	 * True for a cron command safe to place in a crontab line. It runs AS the jailed
321	 * user (crontab -u <user>), so it is already confined; the only invariants we
322	 * enforce here protect our own crontab writer: no newlines (one line per job) and
323	 * no `%` (cron's literal-newline metacharacter), and a sane length.
324	 */
325	export function isValidCronCommand(command: string): boolean {
326	  const c = String(command ?? "");
327	  if (c.length < 1 || c.length > 500) return false;
328	  return !/[\n\r%]/.test(c);
329	}
330	
331	/* ------------------------------------------------------------------------- *
332	 * Provisioner hardening (config generators for NEW accounts)
333	 *
334	 * These are the security-critical config the provisioner writes onto a
335	 * MULTI-TENANT box. They are pure + unit-tested here because a subtle gap in
336	 * any of them (a missing dangerous PHP function, a world-readable webroot, an
337	 * un-escaped GRANT wildcard) is not one customer's bug — it is a cross-tenant
338	 * breach. worker/hosting.ts imports these; it never re-derives them inline.
339	 * ------------------------------------------------------------------------- */
340	
341	/**
342	 * PHP functions blocked in every account's FPM pool (`disable_functions`).
343	 *
344	 * On a shared box `disable_functions` is a real isolation control, not defence
345	 * in depth: without it a tenant's PHP can shell out (`exec`/`system`), fork out
346	 * of `open_basedir` (`pcntl_exec` — compiled into PHP, so it bypasses a naive
347	 * blocklist), rewrite its own env (`putenv` → `LD_PRELOAD`/`GCONV_PATH`
348	 * tricks), plant symlinks that escape the jail (`symlink`/`link`), or reach the
349	 * host via `ffi`/`dl`. Everything a tenant could use to break out of its pool
350	 * belongs here. Kept sorted-by-purpose + deduped.
351	 */
352	export const PHP_DISABLED_FUNCTIONS: readonly string[] = [
353	  // Command execution — the classic RCE surface.
354	  "exec", "passthru", "shell_exec", "system", "proc_open", "popen",
355	  // Process control — pcntl_exec is compiled in and bypasses the above blocklist;
356	  // fork/signal/proc_nice let a tenant escape open_basedir or starve neighbours.
357	  "pcntl_exec", "pcntl_fork", "pcntl_signal", "proc_nice",
358	  // Environment + dynamic loading — putenv enables LD_PRELOAD-style escapes,
359	  // dl/ffi load native code straight past the PHP sandbox.
360	  "putenv", "dl", "ffi",
361	  // Filesystem jail-breaks — symlink/link can point out of open_basedir.
362	  "symlink", "link",
363	  // Mail — a shared box is a prized spam relay. mail() is blocked; mb_send_mail
364	  // is an equivalent wrapper, and imap_open/imap_mail can send too — block all.
365	  "mail", "mb_send_mail", "imap_open", "imap_mail",
366	  // Misc host-reach / info-leak vectors.
367	  "error_log", "curl_multi_exec", "parse_ini_file", "show_source",
368	] as const;
369	
370	/** The comma-separated `disable_functions` value for a pool config. */
371	export function phpDisableFunctions(): string {
372	  return [...PHP_DISABLED_FUNCTIONS].join(",");
373	}
374	
375	/**
376	 * Filesystem ownership + permission plan for a new account.
377	 *
378	 * The isolation goal: nginx (www-data) must serve a tenant's files, but a
379	 * NEIGHBOURING tenant (its own jailed unix user) must not be able to read them
380	 * — so nothing here is world-readable (the old `755` webroot let any tenant
381	 * read a peer's wp-config.php if open_basedir was ever escaped).
382	 *
383	 *  - home    `711 root:root` — chroot-safe (root-owned, no group/other write)
384	 *            and world-traversable so nginx can *reach* the webroot, but NOT
385	 *            world-listable, so a peer can't enumerate the home.
386	 *  - webroot `2750 <user>:www-data` — owner (the tenant's FPM pool) read/write,
387	 *            group www-data (nginx) read, world nothing. The setgid bit makes
388	 *            files the tenant creates inherit the www-data group so nginx keeps
389	 *            serving them; peers (neither owner nor in www-data) are shut out.
390	 *  - tmp     `700 <user>:<user>` — private PHP scratch (upload/session dir).
391	 *
392	 * nginx reaches tenant files via GROUP membership (www-data owns the webroot
393	 * group), never via world bits — that is the whole point of dropping 755.
394	 */
395	export function accountFsPlan(username: string): {
396	  home: { owner: string; mode: string };
397	  webroot: { owner: string; mode: string };
398	  tmp: { owner: string; mode: string };
399	  nginxGroup: string;
400	} {
401	  return {
402	    home: { owner: "root:root", mode: "711" },
403	    webroot: { owner: `${username}:www-data`, mode: "2750" },
404	    tmp: { owner: `${username}:${username}`, mode: "700" },
405	    nginxGroup: "www-data",
406	  };
407	}
408	
409	/** PHP-FPM pool hardening limits applied to every account pool. */
410	export const FPM_MEMORY_LIMIT = "256M";
411	export const FPM_REQUEST_TERMINATE_TIMEOUT = "120s";
412	
413	/**
414	 * The per-account PHP-FPM pool config (the PHP isolation boundary). Pure: given
415	 * the validated username + jailed paths, returns the exact pool file contents.
416	 *
417	 * open_basedir is scoped to the account home (+ the shared PHP lib) and NO
418	 * LONGER includes `/tmp`: PHP's tmp/session dirs are redirected into the home,
419	 * so a world-writable `/tmp` on open_basedir was just an unnecessary shared
420	 * surface between tenants. memory_limit + request_terminate_timeout cap a
421	 * single tenant from exhausting the shared box.
422	 */
423	export function fpmPoolConfig(username: string, home: string, webroot: string): string {
424	  const sock = `/run/php/${username}.sock`;
425	  return [
426	    `[${username}]`,
427	    `user = ${username}`,
428	    `group = ${username}`,
429	    `listen = ${sock}`,
430	    `listen.owner = ${username}`,
431	    `listen.group = www-data`,
432	    `pm = ondemand`,
433	    `pm.max_children = 6`,
434	    `pm.process_idle_timeout = 30s`,
435	    `chdir = ${webroot}`,
436	    // TRAILING SLASHES are load-bearing: `${home}` (no slash) would also authorise
437	    // `${home}2/…` — a sibling tenant's home — so open_basedir must pin the prefix
438	    // to the directory itself via the trailing `/` (same for the shared PHP lib).
439	    `php_admin_value[open_basedir] = ${home}/:/usr/share/php/`,
440	    `php_admin_value[disable_functions] = ${phpDisableFunctions()}`,
441	    `php_admin_value[memory_limit] = ${FPM_MEMORY_LIMIT}`,
442	    `php_admin_value[request_terminate_timeout] = ${FPM_REQUEST_TERMINATE_TIMEOUT}`,
443	    `php_admin_value[upload_tmp_dir] = ${home}/tmp`,
444	    `php_admin_value[session.save_path] = ${home}/tmp`,
445	  ].join("\n");
446	}
447	
448	/**
449	 * Escape a MySQL identifier for the `ON <db>.*` clause of a GRANT.
450	 *
451	 * In GRANT, `_` and `%` are LIKE-wildcards: an un-escaped grant on `nxuser_wp`
452	 * silently also grants on `nxuserXwp`, `nxuser_wpZ`, … i.e. a neighbouring
453	 * tenant's database. Escaping them (and the escape char itself) with a
454	 * backslash pins the grant to exactly one database.
455	 */
456	export function escapeGrantDbName(name: string): string {
457	  return name.replace(/([\\_%])/g, "\\$1");
458	}
459	
460	/**
461	 * The scoped SQL that creates one account database + user and grants that user
462	 * privileges on THAT DATABASE ONLY.
463	 *
464	 * Security invariants (audited): the GRANT is pinned to the exact db via
465	 * escapeGrantDbName (no wildcard bleed into a peer's db), it is NEVER `*.*`,
466	 * and `ALL PRIVILEGES` at database scope confers no global FILE/SUPER (those
467	 * are server-level and cannot be granted by a db-scoped GRANT). Returns plain
468	 * SQL with real backticks; the caller shell-escapes for `mysql -e`.
469	 */
470	export function buildScopedGrantSql(dbName: string, dbUser: string, dbPass: string): string {
471	  const grantName = escapeGrantDbName(dbName);
472	  return (
473	    `CREATE DATABASE IF NOT EXISTS \`${dbName}\`; ` +
474	    `CREATE USER IF NOT EXISTS '${dbUser}'@'localhost' IDENTIFIED BY '${dbPass}'; ` +
475	    `GRANT ALL PRIVILEGES ON \`${grantName}\`.* TO '${dbUser}'@'localhost'; ` +
476	    `FLUSH PRIVILEGES;`
477	  );
478	}
