480	// ---- Proprietary in-portal DB manager (Nxeon-built, replaces Adminer) -------
481	
482	/** The account-level MySQL user the in-portal DB manager authenticates as. One
483	 *  per account, derived from the (already shell/SQL-safe) username. Kept <=32
484	 *  chars — MySQL's user-name limit. Usernames are `[a-z][a-z0-9]{2,31}` (no
485	 *  underscore), so `<username>_mgr` is unambiguous and never collides with a
486	 *  per-database user (`<username>_<slug>`) whose slug can't be the reserved
487	 *  literal `mgr` used here… — we simply reserve this name for the manager. */
488	export function dbMgrUserFor(username: string): string {
489	  return `${username}_mgr`.slice(0, 32);
490	}
491	
492	/** Is this a syntactically valid MySQL account/database identifier for OUR
493	 *  generated names? Deliberately strict — only the charset our provisioner ever
494	 *  produces (`<username>_<slug>` / `<username>_mgr`), so a value that reaches the
495	 *  `mysql` command line as a flag can carry no shell metacharacters. NOT for
496	 *  arbitrary user-supplied table names (those are validated by membership against
497	 *  SHOW TABLES + backtick-quoting, never interpolated into a shell). */
498	const DB_IDENT_RE = /^[a-z0-9_]{1,64}$/;
499	export function isValidDbIdentifier(name: string): boolean {
500	  return DB_IDENT_RE.test(String(name ?? ""));
501	}
502	
503	/**
504	 * The grant that scopes the DB-manager user to EXACTLY this account's own
505	 * databases and nothing else. The privilege target is `<username>\_%`.* — the
506	 * account username, a LITERAL underscore (escaped so it is not a LIKE wildcard),
507	 * then `%`. That matches every `<username>_<...>` database the account can create
508	 * and, because usernames are `[a-z][a-z0-9]{2,31}` (never contain `_`), can never
509	 * match another tenant's `<otheruser>_<...>` databases — the same escaped-glob
510	 * boundary the backup/terminate paths already rely on.
511	 *
512	 * Security invariants (mirror buildScopedGrantSql): the grant is db-scoped, never
513	 * `*.*`, so `ALL PRIVILEGES` here confers NO server-level FILE/PROCESS/SUPER — the
514	 * manager user therefore cannot read files (LOAD_FILE/INTO OUTFILE), see other
515	 * connections, or touch the `mysql`/system schemas. Returns plain SQL with real
516	 * backticks; the caller shell-escapes for `mysql -e`.
517	 */
518	export function buildDbMgrGrantSql(username: string, mgrUser: string, mgrPass: string): string {
519	  // `${username}\_%` — escape only the underscore (username itself is [a-z0-9]).
520	  const scope = `${username}\\_%`;
521	  return (
522	    `CREATE USER IF NOT EXISTS '${mgrUser}'@'localhost' IDENTIFIED BY '${mgrPass}'; ` +
523	    `ALTER USER '${mgrUser}'@'localhost' IDENTIFIED BY '${mgrPass}'; ` +
524	    `GRANT ALL PRIVILEGES ON \`${scope}\`.* TO '${mgrUser}'@'localhost'; ` +
525	    `FLUSH PRIVILEGES;`
526	  );
527	}
