72	const STEP_TIMEOUT_MS = 60_000;
73	/** Node hardening runs the whole onboard script (apt installs — ModSecurity,
74	 *  ClamAV — take minutes), so it gets a much longer ceiling than a single step. */
75	const HARDEN_TIMEOUT_MS = 15 * 60_000;
