89	async function connectNode(node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null }): Promise<Client> {
90	  const password = node.rootPasswordEnc ? decryptSecret(node.rootPasswordEnc) : "";
91	  if (!password) throw new Error("Hosting node has no root credential on record.");
92	  const conn = new Client();
93	  await new Promise<void>((resolve, reject) => {
94	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
95	    conn
96	      .on("ready", () => { clearTimeout(timer); resolve(); })
97	      .on("error", (e) => { clearTimeout(timer); reject(e); })
98	      .connect({ host: node.sshHost, port: node.sshPort, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
99	  });
100	  return conn;
101	}
102	
103	function exec(conn: Client, command: string, timeoutMs = STEP_TIMEOUT_MS): Promise<{ code: number; out: string }> {
104	  return new Promise((resolve, reject) => {
105	    const timer = setTimeout(() => reject(new Error("command timed out")), timeoutMs);
106	    conn.exec(command, (err, stream) => {
107	      if (err) { clearTimeout(timer); return reject(err); }
108	      let out = "";
109	      stream
110	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); })
111	        .on("data", (d: Buffer) => { out += d.toString(); })
112	        .stderr.on("data", (d: Buffer) => { out += d.toString(); });
113	    });
114	  });
115	}
116	
117	async function run(conn: Client, label: string, cmd: string): Promise<void> {
118	  const r = await exec(conn, cmd, STEP_TIMEOUT_MS);
119	  if (r.code !== 0) throw new Error(`${label} failed: ${r.out.slice(0, 300)}`);
120	}
