122	/**
123	 * The name-based nginx vhost for one account. It ALWAYS emits a `listen 443 ssl`
124	 * server block so nginx answers HTTPS from the moment the account exists —
125	 * `ssl.certDir` is the real Let's Encrypt live dir when `ssl.real` is true, else
126	 * the per-account SELF-SIGNED fallback generated at provision time. That is the
127	 * whole "clean setup always" guarantee: HTTPS shows a cert WARNING, never
128	 * ERR_CONNECTION_REFUSED. The HTTP→HTTPS redirect fires ONLY once a real cert
129	 * exists; a self-signed site still serves its body over both 80 and 443 (so it
130	 * can't 301-loop a visitor into an untrusted-cert dead end). Shared IP; routed
131	 * purely by server_name; PHP proxied to THIS account's socket only, root jailed to
132	 * its webroot. Pure string — no interpolation reaches a shell here.
133	 */
134	function renderHostingVhost(username: string, domain: string, webroot: string, sock: string, ssl: { certDir: string; real: boolean }): string {
135	  const phpLoc = [
136	    `    location ~ \\.php$ {`,
137	    `        include fastcgi_params;`,
138	    `        fastcgi_pass unix:${sock};`,
139	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
140	    `    }`,
141	  ].join("\n");
142	  const body = [
143	    `    root ${webroot};`,
144	    // Refuse to follow a symlink whose target isn't owned by the same user as the
145	    // link — blocks a tenant symlinking to a victim's wp-config.php that nginx
146	    // (www-data) would otherwise happily serve (cross-tenant read, audit CRITICAL-1).
147	    `    disable_symlinks if_not_owner;`,
148	    `    index index.php index.html;`,
149	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
150	    phpLoc,
151	    `    location ~ /\\. { deny all; }`,
152	  ].join("\n");
153	  const http = [
154	    `server {`,
155	    `    listen 80;`,
156	    `    listen [::]:80;`,
157	    `    server_name ${domain} www.${domain};`,
158	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
159	    // Redirect to HTTPS only with a REAL cert; a self-signed site serves over 80 too.
160	    ssl.real ? `    location / { return 301 https://$host$request_uri; }` : body,
161	    `}`,
162	  ].join("\n");
163	  const https = [
164	    `server {`,
165	    `    listen 443 ssl;`,
166	    `    listen [::]:443 ssl;`,
167	    `    server_name ${domain} www.${domain};`,
168	    `    ssl_certificate ${ssl.certDir}/fullchain.pem;`,
169	    `    ssl_certificate_key ${ssl.certDir}/privkey.pem;`,
170	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
171	    body,
172	    `}`,
173	  ].join("\n");
174	  return `${http}\n${https}\n`;
175	}
