236	  const path = `/etc/nginx/sites-available/hosting-${key}.conf`;
237	  await run(conn, "write site vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${key}.conf`);
238	  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
