452	/**
453	 * For each ACTIVE account without HTTPS, once its domain resolves to the node's
454	 * shared IP, issue a per-domain cert (webroot) and upgrade the vhost to a 443 SNI
455	 * block. Safe: touches only nginx + certbot, never sshd.
456	 */
457	export async function hostingSslSweep(): Promise<void> {
458	  if (SANDBOX || !ENABLED) return;
459	  const accts = await db.hostingAccount.findMany({
460	    where: { status: "ACTIVE", sslActive: false },
461	    include: { node: true },
462	    take: 20,
463	  });
464	  for (const a of accts) {
465	    try {
466	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
467	      if (!(await domainPointsAt(a.primaryDomain, a.node.publicIp))) continue; // DNS not pointed yet
468	      const d = a.primaryDomain;
469	      const conn = await connectNode(a.node);
470	      try {
471	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
472	        const liveDir = `/etc/letsencrypt/live/${d}`;
473	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
474	        if (have.out.trim() !== "yes") { console.log(`[hosting] cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
475	        const { webroot } = accountPaths(a.username);
476	        await installVhost(conn, a.username, renderHostingVhost(a.username, d, webroot, `/run/php/${a.username}.sock`, { certDir: liveDir, real: true }));
477	      } finally {
478	        try { conn.end(); } catch { /* */ }
479	      }
480	      await db.hostingAccount.update({ where: { id: a.id }, data: { sslActive: true } });
481	      console.log(`[hosting] HTTPS active for ${a.primaryDomain}`);
482	    } catch (e) {
483	      console.error(`[hosting] ssl sweep ${a.id} failed`, e);
484	    }
485	  }
486	
487	  // Addon domains get their own per-domain cert the same way, once they resolve
488	  // to the node's shared IP. (Subdomains are folded into the account cert below.)
489	  const addons = await db.hostingAddonDomain.findMany({
490	    where: { status: "ACTIVE", sslActive: false },
491	    include: { account: { include: { node: true } } },
492	    take: 20,
493	  });
494	  for (const ad of addons) {
495	    try {
496	      const u = ad.account.username;
497	      const d = ad.domain;
498	      if (!isValidHostingDomain(d) || !isValidUnixUsername(u)) continue;
499	      if (!(await domainPointsAt(d, ad.account.node.publicIp))) continue; // DNS not pointed yet
500	      const conn = await connectNode(ad.account.node);
501	      try {
502	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
503	        const liveDir = `/etc/letsencrypt/live/${d}`;
504	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
505	        if (have.out.trim() !== "yes") { console.log(`[hosting] addon cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
506	        const { docroot } = addonDomainPaths(u, d);
507	        await installNamedVhost(conn, `${u}-${d}`, renderSiteVhost(`${d} www.${d}`, docroot, `/run/php/${u}.sock`, liveDir));
508	      } finally {
509	        try { conn.end(); } catch { /* */ }
510	      }
511	      await db.hostingAddonDomain.update({ where: { id: ad.id }, data: { sslActive: true } });
512	      console.log(`[hosting] HTTPS active for addon ${d}`);
513	    } catch (e) {
514	      console.error(`[hosting] addon ssl sweep ${ad.id} failed`, e);
515	    }
516	  }
517	
518	  // Subdomains: fold each into its ACCOUNT'S existing Let's Encrypt cert as an
519	  // extra SAN once it resolves to the node, then serve 443 for it off that same
520	  // live dir. We reuse the account cert (HTTP-01 webroot, --expand) rather than a
521	  // wildcard: a wildcard needs DNS-01 + a DNS-provider API we don't hold (customers
522	  // self-manage their DNS), whereas SAN expansion works off the pointed A record —
523	  // the same flow every other cert here uses. The subdomain's HTTP vhost already
524	  // proxies /.well-known/acme-challenge to /var/www/html, so the challenge serves.
525	  const pendingSubs = await db.hostingSubdomain.findMany({
526	    where: { status: "ACTIVE", sslActive: false },
527	    include: { account: { include: { node: true } } },
528	    take: 30,
529	  });
530	  // One reissue per account per sweep even if several of its subdomains are pending
531	  // — the reissue covers them all at once, and each is verified independently below.
532	  const seenAccounts = new Set<string>();
533	  for (const sub of pendingSubs) {
534	    if (seenAccounts.has(sub.accountId)) continue;
535	    seenAccounts.add(sub.accountId);
536	    try {
537	      const a = sub.account;
538	      const u = a.username;
539	      const primary = a.primaryDomain;
540	      if (!isValidHostingDomain(primary) || !isValidUnixUsername(u)) continue;
541	      const liveDir = `/etc/letsencrypt/live/${primary}`;
542	      // All ACTIVE subdomains of this account, and which of them already resolve to
543	      // us. Only names that resolve are folded in, so certbot never churns on a name
544	      // it can't validate and the SAN set stays stable between ticks (idempotent).
545	      const active = await db.hostingSubdomain.findMany({ where: { accountId: a.id, status: "ACTIVE" } });
546	      const resolving: typeof active = [];
547	      for (const s of active) {
548	        if (!isValidSubdomainLabel(s.label)) continue;
549	        const fqdn = `${s.label}.${primary}`;
550	        if (!isValidHostingDomain(fqdn)) continue;
551	        if (await domainPointsAt(fqdn, a.node.publicIp)) resolving.push(s);
552	      }
553	      // Nothing to do until at least one not-yet-secured subdomain resolves to us.
554	      if (!resolving.some((s) => !s.sslActive)) continue;
555	      const conn = await connectNode(a.node);
556	      try {
557	        // The account cert must already exist (the primary sweep mints it once the
558	        // primary resolves). If it doesn't yet, leave it to that sweep and retry.
559	        if ((await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`)).out.trim() !== "yes") continue;
560	        // SAN set = primary + www + every already-secured sub (never drop a live one)
561	        // + every currently-resolving sub. --cert-name pins the lineage to <primary>
562	        // so the live dir path is stable; --expand folds in the new SANs; --allow-
563	        // subset-of-names keeps a name that isn't pointed from aborting the cert;
564	        // --keep-until-expiring makes a no-op reissue idempotent when nothing changed.
565	        const keep = active.filter(
566	          (s) => (s.sslActive || resolving.includes(s)) && isValidSubdomainLabel(s.label) && isValidHostingDomain(`${s.label}.${primary}`),
567	        );
568	        const dflags = [primary, `www.${primary}`, ...keep.map((s) => `${s.label}.${primary}`)].map((n) => `-d ${n}`).join(" ");
569	        await exec(
570	          conn,
571	          `certbot certonly --webroot -w /var/www/html --cert-name ${primary} ${dflags} --expand --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`,
572	          3 * 60_000,
573	        );
574	        // The reissue rewrote the cert in place. For each newly-securable sub, confirm
575	        // the cert now actually carries it as a SAN (a name whose challenge failed was
576	        // dropped by --allow-subset-of-names), then serve 443 for it off the account
577	        // live dir — installNamedVhost's nginx reload also loads the expanded cert.
578	        for (const s of resolving) {
579	          if (s.sslActive) continue; // already serving HTTPS — leave it untouched
580	          const fqdn = `${s.label}.${primary}`;
581	          const covered = (await exec(conn, `openssl x509 -in ${liveDir}/fullchain.pem -noout -text 2>/dev/null | grep -qiF 'DNS:${fqdn}' && echo yes || echo no`)).out.trim() === "yes";
582	          if (!covered) { console.log(`[hosting] subdomain ${fqdn} not yet in cert — retrying next tick`); continue; }
583	          const { docroot } = subdomainPaths(u, s.label);
584	          await installNamedVhost(conn, `${u}-${s.label}`, renderSiteVhost(fqdn, docroot, `/run/php/${u}.sock`, liveDir));
585	          await db.hostingSubdomain.update({ where: { id: s.id }, data: { sslActive: true } });
586	          console.log(`[hosting] HTTPS active for subdomain ${fqdn}`);
587	        }
588	      } finally {
589	        try { conn.end(); } catch { /* */ }
590	      }
591	    } catch (e) {
592	      console.error(`[hosting] subdomain ssl sweep ${sub.accountId} failed`, e);
593	    }
594	  }
595	}
