703	// ---- Serve-verification + self-heal health sweep ---------------------------
704	
705	/** Parse the numeric HTTP status curl printed with `-w '%{http_code}'`. Returns 0
706	 *  when curl couldn't get a response (connection refused/timeout → "000"). */
707	function parseHttpCode(out: string): number {
708	  const n = parseInt(out.trim().slice(-3), 10);
709	  return Number.isFinite(n) ? n : 0;
710	}
711	/** A 2xx/3xx means nginx actually answered with a page/redirect for this vhost —
712	 *  the anti-ERR_CONNECTION_REFUSED signal. 4xx/5xx/000 are NOT counted as serving
713	 *  (we never mark an account falsely healthy). */
714	function servesOk(code: number): boolean {
715	  return code >= 200 && code < 400;
716	}
717	
718	/**
719	 * Serve-verification + self-heal for ACTIVE accounts. From the node itself it
720	 * curls http/https for each account's own Host header and records whether nginx
721	 * genuinely answers on 80/443 (serveHttpOk / serveHttpsOk) — so the panel reflects
722	 * REALITY, never "active" while HTTPS refuses (the kaymo failure). It also
723	 * SELF-HEALS: if a real Let's Encrypt cert exists but 443 isn't serving, it
724	 * reinstalls the real-cert vhost and reloads nginx; if HTTPS just isn't issued yet
725	 * it's left to hostingSslSweep. Gated ENABLED && !SANDBOX like every other node
726	 * path. `onlyRequested` processes just the accounts a customer clicked "Check now"
727	 * on (recheckRequested), so the button feels immediate; the full sweep runs on the
728	 * ~10-min tick. Returns the number of accounts processed.
729	 */
730	export async function hostingHealthSweep(opts: { onlyRequested?: boolean } = {}): Promise<number> {
731	  const onlyRequested = opts.onlyRequested === true;
732	  if (SANDBOX) {
733	    // Simulate a healthy check so the dev panel + the "Check now" button resolve,
734	    // and the recheck flag clears. HTTPS "verified" mirrors the (simulated) sslActive.
735	    const accts = await db.hostingAccount.findMany({
736	      where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
737	      select: { id: true, sslActive: true },
738	      take: onlyRequested ? 25 : 50,
739	    });
740	    for (const a of accts) {
741	      await db.hostingAccount.update({
742	        where: { id: a.id },
743	        data: {
744	          serveHttpOk: true,
745	          serveHttpsOk: true,
746	          healthNote: a.sslActive ? "HTTPS live — verified" : "HTTP live, HTTPS issuing",
747	          healthCheckedAt: new Date(),
748	          recheckRequested: false,
749	        },
750	      }).catch(() => undefined);
751	    }
752	    return accts.length;
753	  }
754	  if (!ENABLED) return 0;
755	
756	  const accts = await db.hostingAccount.findMany({
757	    where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
758	    include: { node: true },
759	    // Newest-requested first so a customer who just clicked "Check now" is served
760	    // before the routine backlog even in the full sweep.
761	    orderBy: [{ recheckRequested: "desc" }, { updatedAt: "asc" }],
762	    take: onlyRequested ? 25 : 30,
763	  });
764	  let processed = 0;
765	  for (const a of accts) {
766	    try {
767	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
768	      const d = a.primaryDomain;
769	      const u = a.username;
770	      let serveHttpOk = false;
771	      let serveHttpsOk = false;
772	      let sslActive = a.sslActive;
773	      let note = "";
774	      const conn = await connectNode(a.node);
775	      try {
776	        const httpR = await exec(conn, `curl -s -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' http://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
777	        const httpsR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
778	        serveHttpOk = servesOk(parseHttpCode(httpR.out));
779	        serveHttpsOk = servesOk(parseHttpCode(httpsR.out));
780	
781	        // Does a REAL Let's Encrypt cert exist on the node for this domain?
782	        const liveDir = `/etc/letsencrypt/live/${d}`;
783	        const haveReal = (await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`)).out.trim() === "yes";
784	
785	        // SELF-HEAL: a real cert exists but 443 isn't serving → the vhost is stale
786	        // or nginx dropped the block. Reinstall the real-cert vhost + reload, then
787	        // re-verify. This is the recovery from exactly the state kaymo hit.
788	        if (haveReal && !serveHttpsOk) {
789	          const { webroot } = accountPaths(u);
790	          try {
791	            await installVhost(conn, u, renderHostingVhost(u, d, webroot, `/run/php/${u}.sock`, { certDir: liveDir, real: true }));
792	            const reR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
793	            serveHttpsOk = servesOk(parseHttpCode(reR.out));
794	            if (serveHttpsOk) note = "Recovered HTTPS (reinstalled certificate vhost)";
795	          } catch (e) {
796	            note = "HTTPS repair failed — support notified";
797	            console.error(`[hosting] health self-heal ${a.id} failed`, e);
798	          }
799	        }
800	        if (haveReal && serveHttpsOk) sslActive = true; // real cert is live
801	
802	        if (!note) {
803	          if (sslActive && serveHttpsOk) note = "HTTPS live — verified";
804	          else if (serveHttpsOk || serveHttpOk) note = "HTTP live, HTTPS issuing";
805	          else {
806	            // Nothing served locally. If DNS isn't pointed at us yet, say so;
807	            // otherwise it's a serving fault the SSL sweep / support will chase.
808	            const pointed = await domainPointsAt(d, a.node.publicIp);
809	            note = pointed ? "Serving issue — being checked" : "DNS not detected yet";
810	          }
811	        }
812	      } finally {
813	        try { conn.end(); } catch { /* */ }
814	      }
815	      await db.hostingAccount.update({
816	        where: { id: a.id },
817	        data: { serveHttpOk, serveHttpsOk, sslActive, healthNote: note.slice(0, 200), healthCheckedAt: new Date(), recheckRequested: false },
818	      });
819	      processed++;
820	    } catch (e) {
821	      console.error(`[hosting] health sweep ${a.id} failed`, e);
822	      // Clear the recheck flag even on failure so a broken node can't wedge the
823	      // fast path into re-processing the same account every 30s forever.
824	      await db.hostingAccount.update({ where: { id: a.id }, data: { recheckRequested: false } }).catch(() => undefined);
825	    }
826	  }
827	  return processed;
