884	/** Fully deprovision: remove the vhost + FPM pool, delete the jailed user and its
885	 *  home, and drop every database AND db-user scoped to this account (`<user>_*`). */
886	async function taskTerminate(conn: Client, a: LifecycleAccount): Promise<void> {
887	  assertLifecycleSafe(a);
888	  await run(conn, "terminate: remove vhost", `rm -f /etc/nginx/sites-enabled/hosting-${a.username}.conf /etc/nginx/sites-available/hosting-${a.username}.conf; systemctl reload nginx 2>/dev/null || true`);
