1005	/** Archive the account's home + DB dumps to a node-local backups dir.
1006	 *
1007	 * SECURITY (audit 2026-08-01, cross-tenant DB compromise): the DB dumps are
1008	 * written to a ROOT-ONLY directory OUTSIDE the tenant's chroot and are NEVER
1009	 * chowned to the tenant. The old code dumped into ${home}/.dbdump and chowned it
1010	 * to the account user, so the tenant — who holds live SFTP creds chrooted to
1011	 * ${home} — could race in and overwrite <db>.sql with arbitrary SQL that restore
1012	 * later piped into `mysql` as root (a shared-node-wide GRANT/USE). Keeping the
1013	 * dumps root-owned and off the tenant tree means the archived SQL is always our
1014	 * own mysqldump output, never tenant-controlled. */
1015	async function taskBackup(conn: Client, a: { id: string; username: string }, tsLabel: string): Promise<void> {
1016	  const u = a.username;
1017	  const dir = `/var/hosting-backups/${u}`;
1018	  const dumpDir = `${dir}/dbdump`;
1019	  const path = `${dir}/${tsLabel}.tar.gz`;
1020	  // Root-only staging for the DB dumps; the whole dir is 700 root:root so the
1021	  // tenant can neither read nor tamper with it.
1022	  await run(
1023	    conn,
1024	    "dump dbs",
1025	    `rm -rf ${dumpDir}; mkdir -p ${dumpDir}; chown -R root:root ${dir}; chmod 700 ${dir} ${dumpDir}; ` +
1026	      `for dbn in $(mysql -N -e "SHOW DATABASES LIKE '${u}\\_%'" 2>/dev/null); do mysqldump "$dbn" > ${dumpDir}/"$dbn".sql 2>/dev/null; done`,
1027	  );
1028	  // One archive holding the home tree (${u}/…) and the root-owned dumps (dbdump/…).
1029	  await run(conn, "tar home", `tar -czf ${path} -C /home ${u} -C ${dir} dbdump && rm -rf ${dumpDir}`);
1030	  const st = await exec(conn, `stat -c %s ${path} 2>/dev/null || echo 0`);
1031	  const sizeBytes = Math.max(0, Math.min(2_000_000_000, Number(st.out.trim()) || 0));
1032	  await db.hostingBackup.create({ data: { accountId: a.id, path, sizeBytes } });
1033	  // Retain the newest 5 per account; delete older files + rows.
1034	  const all = await db.hostingBackup.findMany({ where: { accountId: a.id }, orderBy: { createdAt: "desc" } });
1035	  for (const old of all.slice(5)) {
1036	    await exec(conn, `rm -f ${old.path}`).catch(() => undefined);
1037	    await db.hostingBackup.delete({ where: { id: old.id } }).catch(() => undefined);
1038	  }
1039	}
