1041	/** Restore a backup over the account (destructive: overwrites files + DBs).
1042	 *
1043	 * The archive is extracted to a ROOT-ONLY staging dir (never straight into the
1044	 * tenant's writable tree), and only DB dumps in THIS tenant's namespace
1045	 * (`${u}_*.sql`) are replayed — so a restore can never touch another tenant's
1046	 * database, and the SQL content is our own dump, not anything the tenant could
1047	 * have planted (see taskBackup). */
1048	async function taskRestore(conn: Client, a: { id: string; username: string }, payload: string | null): Promise<void> {
1049	  const backupId = String(JSON.parse(payload || "{}").backupId ?? "");
1050	  const b = await db.hostingBackup.findFirst({ where: { id: backupId, accountId: a.id } });
1051	  if (!b) throw new Error("backup not found");
1052	  const u = a.username;
1053	  const { home, webroot } = accountPaths(u);
1054	  if (!/^\/var\/hosting-backups\/[a-z0-9]+\/[A-Za-z0-9._-]+\.tar\.gz$/.test(b.path)) throw new Error("unsafe backup path");
1055	  const stage = `/var/hosting-backups/${u}/.restore`;
1056	  await run(conn, "extract", `rm -rf ${stage}; mkdir -p ${stage}; chown root:root ${stage}; chmod 700 ${stage}; tar -xzf ${b.path} -C ${stage}`);
1057	  // Files: the archive root holds ${u}/… — copy it back over the home.
1058	  await run(conn, "restore files", `[ -d ${stage}/${u} ] && cp -a ${stage}/${u}/. ${home}/ 2>/dev/null; true`);
1059	  // DBs: replay ONLY dumps named for this tenant's own databases (${u}_*). The
1060	  // shell `case` guard is belt-and-braces on top of the glob — a dump for
1061	  // another tenant's DB is never fed to mysql.
1062	  await run(
1063	    conn,
1064	    "restore dbs",
1065	    `for f in ${stage}/dbdump/${u}_*.sql; do [ -f "$f" ] || continue; bn=$(basename "$f" .sql); ` +
1066	      `case "$bn" in ${u}_*) mysql "$bn" < "$f" 2>/dev/null;; esac; done`,
1067	  );
1068	  // Re-assert the hardened perms the restored tree may have flattened: webroot
1069	  // stays <user>:www-data setgid (nginx reads via group, peers don't), tmp private.
1070	  const rfs = accountFsPlan(u);
1071	  await run(
1072	    conn,
1073	    "fix perms",
1074	    `chown -R ${rfs.webroot.owner} ${webroot} 2>/dev/null; chmod ${rfs.webroot.mode} ${webroot} 2>/dev/null; ` +
1075	      `chown -R ${rfs.tmp.owner} ${home}/tmp 2>/dev/null; chmod ${rfs.tmp.mode} ${home}/tmp 2>/dev/null; rm -rf ${stage}; true`,
1076	  );
1077	}
