1310	async function processHostingTask(taskId: string): Promise<void> {
1311	  const task = await db.hostingTask.findUnique({ where: { id: taskId }, include: { account: { include: { node: true } } } });
1312	  if (!task || task.status !== "PENDING") return;
1313	  await db.hostingTask.update({ where: { id: task.id }, data: { status: "RUNNING" } });
1314	  const a = task.account;
1315	  // Lifecycle tasks deliberately run on a NON-active account: the admin action
1316	  // flips status to SUSPENDED / DELETING *before* queuing, so gating them on ACTIVE
1317	  // (like the content tasks) would make suspend/terminate silent no-ops — the kill
1318	  // switch must still fire. Content tasks (PHP/WP/backup/restore) stay ACTIVE-only.
1319	  const isLifecycle = task.kind === "SUSPEND" || task.kind === "UNSUSPEND" || task.kind === "TERMINATE";
1320	  if (!isLifecycle && a.status !== "ACTIVE") { await failTask(task.id, "the account is not active"); return; }
1321	  try {
1322	    const conn = await connectNode(a.node);
1323	    try {
1324	      let result: string | null = null;
1325	      if (task.kind === "PHP_SWITCH") await taskPhpSwitch(conn, a, task.payload);
1326	      else if (task.kind === "WORDPRESS_INSTALL") result = await taskWordpressInstall(conn, a, task.payload);
1327	      else if (task.kind === "APP_INSTALL") result = await taskAppInstall(conn, a, task.payload);
1328	      else if (task.kind === "BACKUP") await taskBackup(conn, a, task.id);
1329	      else if (task.kind === "RESTORE") await taskRestore(conn, a, task.payload);
1330	      else if (task.kind === "SUSPEND") await taskSuspend(conn, a);
1331	      else if (task.kind === "UNSUSPEND") await taskUnsuspend(conn, a);
1332	      else if (task.kind === "TERMINATE") await taskTerminate(conn, a);
1333	      else if (task.kind === "CREATE_SUBDOMAIN") await taskCreateSubdomain(conn, a, task.payload);
1334	      else if (task.kind === "DELETE_SUBDOMAIN") await taskDeleteSubdomain(conn, a, task.payload);
1335	      else if (task.kind === "CREATE_ADDON_DOMAIN") await taskCreateAddonDomain(conn, a, task.payload);
1336	      else if (task.kind === "DELETE_ADDON_DOMAIN") await taskDeleteAddonDomain(conn, a, task.payload);
1337	      else if (task.kind === "CREATE_CRON") await taskCreateCron(conn, a, task.payload);
1338	      else if (task.kind === "DELETE_CRON") await taskDeleteCron(conn, a, task.payload);
1339	      else if (task.kind === "INSTALL_DBTOOL") result = await taskInstallDbTool(conn, a, task.payload);
1340	      else if (task.kind === "ENSURE_DBMGR") await taskEnsureDbMgr(conn, a);
1341	      else if (task.kind === "APPLY_PLAN_LIMITS") await taskApplyPlanLimits(conn, a);
1342	      // Cast: the symlinked prod Prisma client's HostingTaskKind predates this new
1343	      // value until it is regenerated at deploy (same as HostingAccount.termMonths).
1344	      else if ((task.kind as string) === "RESET_DB_PASSWORD") await taskResetDbPassword(conn, a, task.payload);
