1350	      // child (tasks incl. this one, databases, subdomains, addons, crons, backups)
1351	      // is onDelete:Cascade, so the account and its history drop in one statement and
1352	      // it disappears from the panel. Financial history rides the user/wallet, not the
1353	      // account, so nothing billable is lost.
1354	      if (task.kind === "TERMINATE") {
