1356	          // Extremely unlikely (all FKs cascade); if it ever fails, at least don't
1357	          // leave it wedged in DELETING — surface it as FAILED so an operator sees it.
1358	          await db.hostingAccount.update({ where: { id: a.id }, data: { status: "FAILED" } }).catch(() => {});
1359	        });
1360	      }
1361	    } finally { try { conn.end(); } catch { /* */ } }
1362	  } catch (e) {
1363	    await failTask(task.id, (e instanceof Error ? e.message : String(e)).slice(0, 300));
1364	  }
1365	}
