/**
 * Opt-in flag for the ONE wildcard TLS cert (`*.<HOSTING_SUBDOMAIN_BASE>`) that
 * gives every free-subdomain site INSTANT trusted HTTPS off a single Let's Encrypt
 * lineage — instead of a per-subdomain HTTP-01 cert (slow AND capped at ~50
 * certs/week per registered domain, a hard wall at ad scale). Read at call time so
 * the whole wildcard path is pure opt-in: when it is not `"1"` every code path
 * behaves EXACTLY as before (self-signed fallback + per-domain sweep).
 */
export function hostingWildcardEnabled(): boolean {
  return process.env.HOSTING_WILDCARD_SSL === "1";
}

/**
 * The certbot `live` dir for the wildcard cert. `--cert-name <base>` pins the
 * lineage to the base zone, so its fullchain/privkey land here — the dir the free-
 * subdomain vhosts point their `ssl_certificate` at when the wildcard is enabled.
 */
export function wildcardCertLiveDir(): string {
  return `/etc/letsencrypt/live/${HOSTING_SUBDOMAIN_BASE}`;
}

/**
 * True when the single-label wildcard cert `*.<HOSTING_SUBDOMAIN_BASE>` ACTUALLY
 * covers `host` — i.e. `host` is exactly one DNS label under the base
 * (`foo.sites.nxeon.cloud`). It deliberately rejects the bare base and any
 * two-label name (`a.b.sites.nxeon.cloud`): a single-label wildcard never matches
 * those, and they don't resolve via the `*.<base>` A record either, so serving the
 * wildcard cert for them would be a name MISMATCH. This is the precise "the
 * wildcard serves this exact name" test the vhost wiring uses — stricter than
 * isFreeSubdomain (which also matches the base + deeper names) on purpose.
 */
export function wildcardCoversHost(host: string): boolean {
  const h = String(host ?? "").trim().toLowerCase().replace(/\.$/, "");
  const suffix = `.${HOSTING_SUBDOMAIN_BASE}`;
  if (!h.endsWith(suffix)) return false;
  const left = h.slice(0, h.length - suffix.length);
  return left.length > 0 && !left.includes(".");
}

