/** True when a non-empty file exists at `path` on the node (`test -s`). Used to
 *  gate real-cert vhosts on the cert actually being present, so nginx -t never
 *  fails on a missing ssl_certificate. `path` is only ever an internally-built
 *  /etc/letsencrypt path, never tenant input. */
async function fileExistsOnNode(conn: Client, path: string): Promise<boolean> {
  const r = await exec(conn, `test -s ${path} && echo yes || echo no`);
  return r.out.trim() === "yes";
}

// ---- Wildcard cert for free subdomains (DNS-01, one cert per node) ----------

/**
 * A Cloudflare DNS API token safe to write into the certbot credentials file:
 * the exact charset Cloudflare mints (alnum plus `_`/`-`), length-bounded, and —
 * crucially — free of any shell/ini metacharacter. It lands in a file, not a
 * command, but an unvalidated secret never goes near a shell here, so we reject
 * anything outside this alphabet.
 */
const CF_TOKEN_RE = /^[A-Za-z0-9_-]{20,120}$/;
/** apt install of certbot + the DNS plugin, and a DNS-01 issuance (30s propagation
 *  wait built in), each run minutes — well past a single node STEP. */
const WILDCARD_STEP_MS = 5 * 60_000;

/**
 * Mint (or renew) the ONE wildcard cert `*.<base>` (+ the apex `<base>`) via
 * certbot DNS-01 against Cloudflare on this node, so every free-subdomain site
 * gets INSTANT trusted HTTPS off a single Let's Encrypt lineage instead of a
 * per-subdomain HTTP-01 cert (slow AND capped at ~50 certs/week per registered
 * domain — a hard wall once signups scale).
 *
 * Fully opt-in + inert: does nothing unless hostingWildcardEnabled() (the
 * HOSTING_WILDCARD_SSL flag) AND a Cloudflare token is present AND shared hosting
 * is enabled AND not sandbox. Idempotent: `--keep-until-expiring` makes a run a
 * no-op until the cert is near expiry (so the ~daily cadence never churns LE), and
 * the credentials file is rewritten `600 root:root` each time. The token is
 * validated to a strict charset BEFORE it is ever written.
 */
export async function ensureWildcardCert(conn: Client): Promise<void> {
  if (SANDBOX || !ENABLED || !hostingWildcardEnabled()) return;
  const token = String(process.env.CLOUDFLARE_DNS_API_TOKEN ?? "").trim();
  if (!token) return; // no credential → silently skip (still inert)
  if (!CF_TOKEN_RE.test(token)) throw new Error("refusing unsafe CLOUDFLARE_DNS_API_TOKEN (charset)");
  const base = HOSTING_SUBDOMAIN_BASE;
  if (!isValidHostingDomain(base)) throw new Error(`refusing unsafe wildcard base ${base}`);

  // 1. certbot + the Cloudflare DNS plugin — only installs when absent (idempotent).
  const inst = await exec(
    conn,
    `if ! command -v certbot >/dev/null 2>&1 || ! python3 -c 'import certbot_dns_cloudflare' >/dev/null 2>&1; then ` +
      `DEBIAN_FRONTEND=noninteractive apt-get update -qq && ` +
      `DEBIAN_FRONTEND=noninteractive apt-get install -y certbot python3-certbot-dns-cloudflare; fi`,
    WILDCARD_STEP_MS,
  );
  if (inst.code !== 0) throw new Error(`wildcard: certbot install failed: ${inst.out.slice(0, 200)}`);

  // 2. Credentials file — root-only (600), written with umask so it is never even
  //    briefly world-readable. Token is validated to [A-Za-z0-9_-] so it is safe
  //    inside the single-quoted printf arg.
  const cred = await exec(
    conn,
    `mkdir -p /etc/letsencrypt && ( umask 077 && printf 'dns_cloudflare_api_token = %s\\n' '${token}' > /etc/letsencrypt/cloudflare.ini ) && ` +
      `chown root:root /etc/letsencrypt/cloudflare.ini && chmod 600 /etc/letsencrypt/cloudflare.ini`,
  );
  if (cred.code !== 0) throw new Error(`wildcard: writing cloudflare.ini failed: ${cred.out.slice(0, 200)}`);

  // 3. Issue/renew the wildcard. --cert-name <base> pins the lineage so the live
  //    dir path (wildcardCertLiveDir) is stable; --keep-until-expiring no-ops until
  //    near expiry. `base` is a validated hostname ([a-z0-9.-]) so it is shell-inert.
  const issue = await exec(
    conn,
    `certbot certonly --dns-cloudflare --dns-cloudflare-credentials /etc/letsencrypt/cloudflare.ini ` +
      `--dns-cloudflare-propagation-seconds 30 -d '*.${base}' -d '${base}' --cert-name ${base} ` +
      `--non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`,
    WILDCARD_STEP_MS,
  );
  const liveDir = wildcardCertLiveDir();
  if (!(await fileExistsOnNode(conn, `${liveDir}/fullchain.pem`))) {
    throw new Error(`wildcard cert not present after issuance: ${issue.out.slice(-240)}`);
  }
  console.log(`[hosting] wildcard cert ready for *.${base} on node`);
}

/**
 * Ensure the wildcard cert exists + is current on EVERY enabled hosting node.
 * Opt-in + inert: no-op unless hostingWildcardEnabled() AND a Cloudflare token is
 * present AND shared hosting is enabled AND not sandbox (ensureWildcardCert
 * re-checks all of these per node too). Runs on a ~daily cadence from the worker;
 * certbot's --keep-until-expiring keeps each tick a cheap no-op until renewal is
 * actually due, so there is no Let's Encrypt rate-limit churn.
 */
export async function hostingWildcardSweep(): Promise<void> {
  if (SANDBOX || !ENABLED || !hostingWildcardEnabled()) return;
  if (!String(process.env.CLOUDFLARE_DNS_API_TOKEN ?? "").trim()) return;
  const nodes = await db.hostingNode.findMany({ where: { enabled: true }, take: 50 });
  for (const node of nodes) {
    try {
      const conn = await connectNode(node);
      try {
        await ensureWildcardCert(conn);
      } finally {
        try { conn.end(); } catch { /* */ }
      }
    } catch (e) {
      console.error(`[hosting] wildcard cert on node ${node.id} failed`, e);
    }
  }
}

